//go:build windows

package main

import (
	"os"
	"runtime"
	"strings"
	"sync"
	"syscall"
	"time"
	"unsafe"

	"github.com/lxn/win"
	"golang.org/x/sys/windows"
)

const (
	appName          = "OK Browser"
	mainClassName    = "OKBrowserMainWnd"
	tabHostClassName = "OKBrowserTabHost"
)

// Hotkey commands (generated by the accelerator table).
const (
	cmdBack         = 201
	cmdForward      = 202
	cmdReload       = 203
	cmdHome         = 204
	cmdFocusAddress = 205
	cmdNewWindow    = 206
	cmdCloseTab     = 207
	cmdZoomIn       = 208
	cmdZoomOut      = 209
	cmdZoomReset    = 210
	cmdPrint        = 211
	cmdFullscreen   = 212
	cmdNextTab      = 213
	cmdPrevTab      = 214
	cmdNewTab       = 215

	// Chrome-compatible additions.
	cmdSelectTab   = 220 // +0..7 for Ctrl+1..8
	cmdLastTab     = 230
	cmdReopenTab   = 231
	cmdHardReload  = 232
	cmdCloseWindow = 233
	cmdFind        = 234
	cmdFindNext    = 235
	cmdFindPrev    = 236
	cmdDevTools    = 237
	cmdBookmark    = 238
	cmdHistoryPage = 239
	cmdBmPage      = 240
	cmdDownloadsPg = 241
	cmdIncognito   = 242
)

// appVersion is shown in the settings page. Release CI overrides it with
// -ldflags so every verified executable carries its automatic build version.
var appVersion = "1.12.2-dev"

// app is the browser window. The entire UI - the Liquid Glass bar with tabs,
// address field and buttons - is rendered inside the web engine as a frosted
// overlay with real backdrop blur; the native side only provides the window
// frame, hotkeys and tab/window management.
type app struct {
	hwnd     win.HWND
	instance win.HINSTANCE
	accel    win.HACCEL

	tabs      []*tab
	activeIdx int
	splitTab   *tab // optional right-hand WebView opened by a link-edge drop
	focusedTab *tab // pane receiving keyboard commands while split
	splitRatio float64 // width of the left pane, 0.28..0.72
	splitResizing bool   // native mouse capture keeps divider drag continuous

	scale float64 // DPI scale factor (1.0 = 96 DPI)

	maximized          bool // window is maximized (drives the shell's max icon)
	pendingBubbleFocus bool // focus the address bubble after the next bar push

	hostSeq int // child window id sequence

	// lastSpawn throttles popup storms from web pages.
	lastSpawn time.Time

	// spare is a pre-warmed, already-painted tab adopted by the next new
	// tab so opening one costs no engine startup (WM_TIMER id 6).
	spare *tab

	// closedTabs remembers recently closed tab URLs for Ctrl+Shift+T.
	closedTabs []string
	downloads []*managedDownload // native WebView2 download operations

	// store is the local data vault: history, bookmarks, settings, session.
	store *store

	// deferred self-test click (WM_TIMER id 3): waits out the new-tab fade.
	stClickTab   *tab
	stClickX     float64
	stClickY     float64
	stClickTicks int

	// new-tab cross-fade state (WM_TIMER id 2).
	fading      bool
	fadeRamping bool
	fadeReady   bool
	fadeHost    win.HWND
	fadePrev    win.HWND
	fadeAlpha   int
	fadeTicks   int

	// taskMu + taskQueue: work posted from engine callbacks, executed in
	// the normal window-proc context via WM_APP. Engine callbacks must not
	// create or destroy engines inline (their nested message pumps clash
	// with the active COM callback), so they post here instead.
	taskMu    sync.Mutex
	taskQueue []func()

	// self test state (--selftest).
	inSelfTest   bool
	selfPhase    int
	selfTestFile *os.File

	// Fullscreen (F11) state.
	fullscreen     bool
	savedStyle     int32
	savedPlacement win.WINDOWPLACEMENT
}

var theApp *app

func wndProc(hwnd win.HWND, msg uint32, wp uintptr, lp unsafe.Pointer) uintptr {
	a := theApp
	if a == nil {
		return win.DefWindowProc(hwnd, msg, wp, uintptr(lp))
	}
	switch msg {
	case win.WM_CREATE:
		a.hwnd = hwnd
		return 0

	case win.WM_SIZE:
		if max := wp == 2; max != a.maximized {
			a.maximized = max
			a.pushBarState() // update the max/restore button icon
		}
		a.layout()
		return 0

	case win.WM_GETMINMAXINFO:
		mmi := (*win.MINMAXINFO)(lp)
		mmi.PtMinTrackSize = win.POINT{X: a.scaled(480), Y: a.scaled(320)}
		return 0

	case win.WM_MOUSEMOVE:
		if a.splitResizing && a.splitTab != nil {
			var rc win.RECT
			if win.GetClientRect(a.hwnd, &rc) && rc.Right > 0 {
				x := win.GET_X_LPARAM(uintptr(lp))
				a.splitRatio = float64(x) / float64(rc.Right)
				if a.splitRatio < .28 { a.splitRatio = .28 }
				if a.splitRatio > .72 { a.splitRatio = .72 }
				a.layout()
			}
			return 0
		}
	case win.WM_LBUTTONUP:
		if a.splitResizing { a.splitResizing = false; win.ReleaseCapture(); a.saveSession(); return 0 }

	case win.WM_COMMAND:
		// Hotkeys arrive here (all buttons live in the glass bar).
		switch win.HIWORD(uint32(wp)) {
		case 0, 1:
			a.onCommand(int(win.LOWORD(uint32(wp))))
		}
		return 0

	case win.WM_APP:
		// Run tasks posted from engine callbacks (see postTask).
		for {
			a.taskMu.Lock()
			var f func()
			if len(a.taskQueue) > 0 {
				f, a.taskQueue = a.taskQueue[0], a.taskQueue[1:]
			}
			a.taskMu.Unlock()
			if f == nil {
				break
			}
			f()
		}
		return 0

	case win.WM_NCCALCSIZE:
		// Frameless geometry - the glass shell bar is the only top bar,
		// windowed or maximized. On entry rgrc[0] holds the PROPOSED
		// window rect in screen coordinates; the client rect must be
		// derived from THAT, never from GetWindowRect - its value can be
		// stale during maximize/restore transitions, which once pushed
		// the whole bar above the visible window after restoring.
		if wp != 0 {
			p := (*ncCalcSizeParams)(lp)
			if win.GetWindowLong(hwnd, win.GWL_STYLE)&win.WS_THICKFRAME == 0 {
				return 0 // F11 fullscreen: the whole window is client
			}
			if placementMaximized(hwnd) {
				// Maximized: the client area is the monitor work area,
				// exactly - no caption band, nothing clipped, taskbar
				// respected.
				var mi win.MONITORINFO
				mi.CbSize = uint32(unsafe.Sizeof(mi))
				if mon := win.MonitorFromWindow(hwnd, win.MONITOR_DEFAULTTONEAREST); mon != 0 && win.GetMonitorInfo(mon, &mi) {
					p.Rc0 = mi.RcWork
				}
				return 0
			}
			// Windowed: keep the resize frame on the sides and bottom
			// (native resize borders + DWM shadow), but pull the client
			// up to the window's top edge so the glass bar is flush.
			fx := int32(win.GetSystemMetrics(win.SM_CXFRAME) + win.GetSystemMetrics(smCXPaddedBorder))
			fy := int32(win.GetSystemMetrics(win.SM_CYFRAME) + win.GetSystemMetrics(smCXPaddedBorder))
			r := p.Rc0
			p.Rc0 = win.RECT{Left: r.Left + fx, Top: r.Top, Right: r.Right - fx, Bottom: r.Bottom - fy}
			return 0
		}
		return 0

	case win.WM_NCHITTEST:
		// WS_POPUP borderless windows: DefWindowProc does not hit-test the
		// resize frame (probing the left border returned HTCLIENT), so do
		// it ourselves - same technique as the classic BorderlessWindow
		// sample. Only the frame band outside the client area reaches the
		// main window (the webview child covers the client), plus the top
		// edge before the engine has mounted.
		if placementMaximized(hwnd) {
			break // maximized: no resize borders, DefWindowProc decides
		}
		{
			lv := uintptr(lp)
			x, y := int32(int16(lv&0xFFFF)), int32(int16((lv>>16)&0xFFFF))
			var wr win.RECT
			if !win.GetWindowRect(hwnd, &wr) {
				break
			}
			bx := int32(win.GetSystemMetrics(win.SM_CXFRAME) + win.GetSystemMetrics(smCXPaddedBorder))
			by := int32(win.GetSystemMetrics(win.SM_CYFRAME) + win.GetSystemMetrics(smCXPaddedBorder))
			left := x < wr.Left+bx
			right := x >= wr.Right-bx
			top := y < wr.Top+by
			bottom := y >= wr.Bottom-by
			switch {
			case left && top:
				return win.HTTOPLEFT
			case right && top:
				return win.HTTOPRIGHT
			case left && bottom:
				return win.HTBOTTOMLEFT
			case right && bottom:
				return win.HTBOTTOMRIGHT
			case left:
				return win.HTLEFT
			case right:
				return win.HTRIGHT
			case top:
				return win.HTTOP
			case bottom:
				return win.HTBOTTOM
			}
		}
		break // client area: DefWindowProc

	case win.WM_TIMER:
		if wp == 1 {
			win.KillTimer(a.hwnd, 1)
			a.pushBarState()
			if a.pendingBubbleFocus {
				a.pendingBubbleFocus = false
				a.execActive("window.__okBubbleFocus&&window.__okBubbleFocus()")
			}
		}
		if wp == 2 {
			a.fadeTick() // new-tab cross-fade
		}
		if wp == 3 {
			a.selftestClickTick()
		}
		if wp == 4 { a.sleepInactiveTabs() }
		if wp == 5 { a.pollDownloads() }
		if wp == 6 { a.warmSpare() }
		return 0

	case win.WM_DPICHANGED:
		a.onDpiChanged(int(win.HIWORD(uint32(wp))), (*win.RECT)(lp))
		return 0

	case win.WM_XBUTTONDOWN:
		// Extra mouse buttons: back / forward.
		switch win.HIWORD(uint32(wp)) {
		case 1:
			a.onCommand(cmdBack)
		case 2:
			a.onCommand(cmdForward)
		}
		return 0

	case win.WM_ERASEBKGND:
		return 1 // the webview covers everything

	case win.WM_ENDSESSION:
		// Windows is logging off or shutting down: WM_DESTROY is not
		// guaranteed to run, so persist the session and the store now.
		if wp != 0 {
			a.saveSession()
			if a.store != nil {
				a.store.Flush()
			}
		}
		return 0
	case win.WM_CLOSE:
		// Closing the window kills the WebView2 processes and with them any
		// transfer still running, leaving a half-written file behind with no
		// warning. Give the user a chance to keep waiting.
		if n := a.activeDownloadCount(); n > 0 && !a.confirmDiscardDownloads(n) {
			return 0
		}
		break // DefWindowProc destroys the window
	case win.WM_DESTROY:
		a.discardSpare()
		a.saveSession()
		if a.store != nil {
			a.store.Flush()
		}
		win.PostQuitMessage(0)
		return 0
	}
	return win.DefWindowProc(hwnd, msg, wp, uintptr(lp))
}

// NewApp creates the main window and the first tab. It returns false when
// the WebView2 runtime is unavailable.
func NewApp(startURL string) (*app, bool) {
	runtime.LockOSThread()

	a := &app{activeIdx: -1}
	a.scale = float64(dpiOf(0)) / 96.0
	a.store = newStore()
	theApp = a

	a.instance = win.GetModuleHandle(nil)
	icon := loadAppIcon(a.instance)
	cursor := win.LoadCursor(0, win.MAKEINTRESOURCE(win.IDC_ARROW))

	if !a.registerClass(mainClassName, windows.NewCallback(wndProc), icon, cursor) {
		return nil, false
	}
	if !a.registerClass(tabHostClassName, windows.NewCallback(defTabHostProc), icon, cursor) {
		return nil, false
	}

	cn, _ := syscall.UTF16PtrFromString(mainClassName)
	title := appName
	if incognitoMode {
		title = appName + " - Incognito"
	}
	tn, _ := syscall.UTF16PtrFromString(title)
	// The classic borderless "aero" style: WS_POPUP combined with
	// WS_CAPTION suppresses the native title bar and DWM's own
	// min/max/close buttons in EVERY window state (plain WS_OVERLAPPEDWINDOW
	// + WM_NCCALCSIZE leaves DWM's floating caption buttons behind), while
	// keeping the DWM animations and shadow, resizing (WS_THICKFRAME),
	// Aero Snap and the system menu. WM_NCCALCSIZE above makes the glass
	// bar the only top bar.
	w, h := a.scaled(1180), a.scaled(820)
	sw, sh := int32(win.GetSystemMetrics(win.SM_CXSCREEN)), int32(win.GetSystemMetrics(win.SM_CYSCREEN))
	x, y := (sw-w)/2, (sh-h)/2 // WS_POPUP ignores CW_USEDEFAULT
	if x < 0 {
		x = 0
	}
	if y < 0 {
		y = 0
	}
	a.hwnd = win.CreateWindowEx(0, cn, tn,
		win.WS_POPUP|win.WS_THICKFRAME|win.WS_CAPTION|win.WS_SYSMENU|
			win.WS_MINIMIZEBOX|win.WS_MAXIMIZEBOX|win.WS_CLIPCHILDREN,
		x, y, w, h,
		0, 0, a.instance, nil)
	if a.hwnd == 0 {
		return nil, false
	}
	// Keep the DWM drop shadow for the borderless window.
	dwmExtendFrame(a.hwnd)

	// Restore the last session when the user wants it and no URL was
	// passed on the command line.
	var sess *sessionData
	if startURL == "" && !selfTestMode && a.store.Settings().RestoreSession {
		sess = a.store.LoadSession()
	}
	if sess != nil && sess.Rect != [4]int32{} {
		showCmd := uint32(win.SW_SHOWNORMAL)
		if sess.Maximized {
			showCmd = win.SW_SHOWMAXIMIZED
		}
		wp := win.WINDOWPLACEMENT{
			Length:  uint32(unsafe.Sizeof(win.WINDOWPLACEMENT{})),
			ShowCmd: showCmd,
			RcNormalPosition: win.RECT{
				Left: sess.Rect[0], Top: sess.Rect[1],
				Right: sess.Rect[2], Bottom: sess.Rect[3],
			},
		}
		win.SetWindowPlacement(a.hwnd, &wp)
	}
	if d := dpiOf(a.hwnd); d > 0 && d != int(a.scale*96) {
		a.scale = float64(d) / 96.0
	}

	a.createAccelerators()

	// Show the window immediately so the browser feels instant; the glass
	// bar and page appear a moment later.
	if sess != nil && sess.Maximized {
		win.ShowWindow(a.hwnd, win.SW_SHOWMAXIMIZED)
	} else {
		win.ShowWindow(a.hwnd, win.SW_SHOW)
	}
	win.UpdateWindow(a.hwnd)

	// The first tab embeds the engine; if the runtime is missing the
	// constructor already showed the download dialog.
	if sess != nil && len(sess.Tabs) > 0 {
		active := sess.Active
		if active < 0 || active >= len(sess.Tabs) {
			active = 0
		}
		for i, st := range sess.Tabs {
			if a.newTab(st.URL, i == active) == nil && i == 0 {
				return nil, false
			}
		}
		a.switchToTab(active)
		if sess.SplitRatio > 0 && sess.Split >= 0 && sess.Split < len(a.tabs) && sess.Split != active {
			a.splitTab = a.tabs[sess.Split]
			a.splitRatio = sess.SplitRatio
			if a.splitRatio < .28 || a.splitRatio > .72 { a.splitRatio = .5 }
			a.layout()
		}
		a.scheduleBarPush(false)
		return a, true
	}
	if a.newTab(startURL, true) == nil {
		return nil, false
	}
	return a, true
}

// saveSession snapshots the open tabs and window state for the next start.
func (a *app) saveSession() {
	if a.store == nil {
		return
	}
	sd := &sessionData{Active: a.activeIdx, Maximized: a.maximized, Split: -1, SplitRatio: a.splitRatio}
	for i, t := range a.tabs { if t == a.splitTab { sd.Split = i; break } }
	for _, t := range a.tabs {
		u := t.url
		if strings.HasPrefix(u, "okbrowser://") {
			u = "" // built-in pages restore as fresh start pages
		}
		sd.Tabs = append(sd.Tabs, sessionTab{URL: u, Title: t.title})
	}
	if len(sd.Tabs) == 0 {
		return // closing the last tab means: start fresh next time
	}
	var wp win.WINDOWPLACEMENT
	wp.Length = uint32(unsafe.Sizeof(wp))
	if win.GetWindowPlacement(a.hwnd, &wp) {
		r := wp.RcNormalPosition
		sd.Rect = [4]int32{r.Left, r.Top, r.Right, r.Bottom}
	}
	a.store.SaveSession(sd)
}

// registerClass registers a window class for the main window or tab hosts.
func (a *app) registerClass(name string, proc uintptr, icon win.HANDLE, cursor win.HCURSOR) bool {
	cn, err := syscall.UTF16PtrFromString(name)
	if err != nil {
		return false
	}
	wc := win.WNDCLASSEX{
		CbSize:        uint32(unsafe.Sizeof(win.WNDCLASSEX{})),
		LpfnWndProc:   proc,
		HInstance:     a.instance,
		HIcon:         win.HICON(icon),
		HCursor:       cursor,
		LpszClassName: cn,
		HIconSm:       win.HICON(icon),
		// Dark erase: a shown-but-unpainted window must never flash white
		// (the default COLOR_WINDOW erase is white).
		HbrBackground: darkBrush(),
	}
	return win.RegisterClassEx(&wc) != 0
}

// defTabHostProc lets tab host windows pass messages to DefWindowProc.
func defTabHostProc(hwnd win.HWND, msg uint32, wp uintptr, lp unsafe.Pointer) uintptr {
	return win.DefWindowProc(hwnd, msg, wp, uintptr(lp))
}

// Run is the Win32 message loop; it returns when the window is closed.
func (a *app) Run() {
	var msg win.MSG
	for {
		r := win.GetMessage(&msg, 0, 0, 0)
		if r <= 0 {
			break
		}
		if translateAccelerator(a.hwnd, a.accel, &msg) != 0 {
			continue
		}
		win.TranslateMessage(&msg)
		win.DispatchMessage(&msg)
	}
}

// loadAppIcon loads the icon embedded by goversioninfo (resource ID 32512).
func loadAppIcon(inst win.HINSTANCE) win.HANDLE {
	for _, id := range []uintptr{32512, 2, 1} {
		if h := win.LoadImage(inst, win.MAKEINTRESOURCE(id), win.IMAGE_ICON,
			0, 0, win.LR_DEFAULTSIZE|win.LR_SHARED); h != 0 {
			return h
		}
	}
	return win.LoadImage(0, win.MAKEINTRESOURCE(win.IDI_APPLICATION), win.IMAGE_ICON,
		0, 0, win.LR_DEFAULTSIZE|win.LR_SHARED)
}

func (a *app) createAccelerators() {
	a.accel = createAcceleratorTable([]accel{
		{fVirtKey | fControl, 'L', cmdFocusAddress},
		{fVirtKey | fAlt, 'D', cmdFocusAddress},
		{fVirtKey | fControl, 'T', cmdNewTab},
		{fVirtKey | fControl, 'N', cmdNewWindow},
		{fVirtKey | fControl, 'W', cmdCloseTab},
		{fVirtKey | fControl, 'R', cmdReload},
		{fVirtKey, win.VK_F5, cmdReload},
		{fVirtKey | fAlt, win.VK_LEFT, cmdBack},
		{fVirtKey | fAlt, win.VK_RIGHT, cmdForward},
		{fVirtKey | fAlt, win.VK_HOME, cmdHome},
		{fVirtKey | fControl, win.VK_TAB, cmdNextTab},
		{fVirtKey | fControl | fShift, win.VK_TAB, cmdPrevTab},
		{fVirtKey | fControl, win.VK_OEM_PLUS, cmdZoomIn},
		{fVirtKey | fControl, win.VK_ADD, cmdZoomIn},
		{fVirtKey | fControl, win.VK_OEM_MINUS, cmdZoomOut},
		{fVirtKey | fControl, win.VK_SUBTRACT, cmdZoomOut},
		{fVirtKey | fControl, '0', cmdZoomReset},
		{fVirtKey | fControl, 'P', cmdPrint},
		{fVirtKey, win.VK_F11, cmdFullscreen},

		// Chrome-compatible additions.
		{fVirtKey | fControl, '1', cmdSelectTab},
		{fVirtKey | fControl, '2', cmdSelectTab + 1},
		{fVirtKey | fControl, '3', cmdSelectTab + 2},
		{fVirtKey | fControl, '4', cmdSelectTab + 3},
		{fVirtKey | fControl, '5', cmdSelectTab + 4},
		{fVirtKey | fControl, '6', cmdSelectTab + 5},
		{fVirtKey | fControl, '7', cmdSelectTab + 6},
		{fVirtKey | fControl, '8', cmdSelectTab + 7},
		{fVirtKey | fControl, '9', cmdLastTab},
		{fVirtKey | fControl, 'K', cmdFocusAddress},
		{fVirtKey | fControl, 'E', cmdFocusAddress},
		{fVirtKey | fControl, 'F', cmdFind},
		{fVirtKey | fControl, 'G', cmdFindNext},
		{fVirtKey | fControl | fShift, 'T', cmdReopenTab},
		{fVirtKey | fControl | fShift, 'R', cmdHardReload},
		{fVirtKey | fControl | fShift, 'W', cmdCloseWindow},
		{fVirtKey | fControl | fShift, 'G', cmdFindPrev},
		{fVirtKey | fControl | fShift, 'I', cmdDevTools},
		{fVirtKey, win.VK_F3, cmdFindNext},
		{fVirtKey | fShift, win.VK_F3, cmdFindPrev},
		{fVirtKey, win.VK_F12, cmdDevTools},
		{fVirtKey | fControl, win.VK_NEXT, cmdNextTab},
		{fVirtKey | fControl, win.VK_PRIOR, cmdPrevTab},
		{fVirtKey | fControl, 'D', cmdBookmark},
		{fVirtKey | fControl, 'H', cmdHistoryPage},
		{fVirtKey | fControl | fShift, 'O', cmdBmPage},
		{fVirtKey | fControl, 'J', cmdDownloadsPg},
		{fVirtKey | fControl | fShift, 'N', cmdIncognito},
	})
}

// layout sizes every tab host to fill the whole window (the glass bar floats
// above the page inside the web content). Only the active host is shown.
func (a *app) layout() {
	if a.hwnd == 0 {
		return
	}
	var rc win.RECT
	if !win.GetClientRect(a.hwnd, &rc) {
		return
	}
	w, h := rc.Right, rc.Bottom
	if w <= 0 || h <= 0 {
		return
	}
	for i, t := range a.tabs {
		isSplit := a.splitTab != nil && t == a.splitTab
		if i == a.activeIdx || isSplit {
			x, width := int32(0), w
			if a.splitTab != nil {
				gap := a.scaled(5)
				ratio := a.splitRatio
				if ratio < .28 || ratio > .72 { ratio = .5 }
				left := int32(float64(w-gap) * ratio)
				if isSplit { x, width = left + gap, w - left - gap } else { width = left }
			}

			if a.fading && t.host == a.fadeHost && !a.fadeRamping {
				// Pending reveal: the new tab stays hidden until its first
				// content has painted - the previous tab shows meanwhile.
			} else {
				win.MoveWindow(t.host, x, 0, width, h, false)
				win.ShowWindow(t.host, win.SW_SHOW)
				if t.chromium != nil {
					t.chromium.Show()
					t.chromium.Resize()
				}
			}
		} else if !a.fading || t.host != a.fadePrev {
			// During a new-tab cross-fade the previous tab stays visible
			// beneath the translucent new one.
			win.ShowWindow(t.host, win.SW_HIDE)
			if t.chromium != nil {
				t.chromium.Hide()
			}
		}
	}
}

// postTask schedules f to run in the normal window-proc context. Engine
// callbacks (web messages, new-window requests) must not do UI work inline;
// they post here and WM_APP executes it.
func (a *app) postTask(f func()) {
	if a.hwnd == 0 {
		return
	}
	a.taskMu.Lock()
	a.taskQueue = append(a.taskQueue, f)
	a.taskMu.Unlock()
	win.PostMessage(a.hwnd, win.WM_APP, 0, 0)
}

// onAccelerator handles hotkeys pressed while a web page has focus (the
// common case now that the whole UI lives inside the page). The engine
// raises this callback for every non-repeat key-down; returning true marks
// the key as handled so the page never sees it.
func (a *app) onAccelerator(vk uint) bool {
	const (
		vkShift   = 0x10
		vkControl = 0x11
		vkMenu    = 0x12 // Alt
	)
	ctrl := keyDown(vkControl)
	shift := keyDown(vkShift)
	alt := keyDown(vkMenu)

	switch {
	case ctrl && !shift && !alt:
		switch vk {
		case 'T':
			a.onCommand(cmdNewTab)
			return true
		case 'W':
			a.onCommand(cmdCloseTab)
			return true
		case 'L':
			a.onCommand(cmdFocusAddress)
			return true
		case 'N':
			a.onCommand(cmdNewWindow)
			return true
		case 'R':
			a.onCommand(cmdReload)
			return true
		case 'P':
			a.onCommand(cmdPrint)
			return true
		case 'K', 'E':
			a.onCommand(cmdFocusAddress)
			return true
		case 'F':
			a.onCommand(cmdFind)
			return true
		case 'G':
			a.onCommand(cmdFindNext)
			return true
		case 'D':
			a.onCommand(cmdBookmark)
			return true
		case 'H':
			a.onCommand(cmdHistoryPage)
			return true
		case 'J':
			a.onCommand(cmdDownloadsPg)
			return true
		case '1', '2', '3', '4', '5', '6', '7', '8':
			a.onCommand(cmdSelectTab + int(vk-'1'))
			return true
		case '9':
			a.onCommand(cmdLastTab)
			return true
		case win.VK_NEXT:
			a.onCommand(cmdNextTab)
			return true
		case win.VK_PRIOR:
			a.onCommand(cmdPrevTab)
			return true
		case '0':
			a.onCommand(cmdZoomReset)
			return true
		case win.VK_TAB:
			a.onCommand(cmdNextTab)
			return true
		case win.VK_OEM_PLUS, win.VK_ADD:
			a.onCommand(cmdZoomIn)
			return true
		case win.VK_OEM_MINUS, win.VK_SUBTRACT:
			a.onCommand(cmdZoomOut)
			return true
		}

	case ctrl && shift && !alt:
		switch vk {
		case win.VK_TAB:
			a.onCommand(cmdPrevTab)
			return true
		case 'T':
			a.onCommand(cmdReopenTab)
			return true
		case 'R':
			a.onCommand(cmdHardReload)
			return true
		case 'W':
			a.onCommand(cmdCloseWindow)
			return true
		case 'G':
			a.onCommand(cmdFindPrev)
			return true
		case 'I':
			a.onCommand(cmdDevTools)
			return true
		case 'O':
			a.onCommand(cmdBmPage)
			return true
		case 'N':
			a.onCommand(cmdIncognito)
			return true
		case win.VK_F3:
			a.onCommand(cmdFindPrev)
			return true
		}

	case alt && !ctrl:
		switch vk {
		case win.VK_LEFT:
			a.onCommand(cmdBack)
			return true
		case win.VK_RIGHT:
			a.onCommand(cmdForward)
			return true
		case win.VK_HOME:
			a.onCommand(cmdHome)
			return true
		}

	case !ctrl && !shift && !alt:
		switch vk {
		case win.VK_F5:
			a.onCommand(cmdReload)
			return true
		case win.VK_F11:
			a.onCommand(cmdFullscreen)
			return true
		case win.VK_F3:
			a.onCommand(cmdFindNext)
			return true
		case win.VK_F12:
			a.onCommand(cmdDevTools)
			return true
		}
	}
	return false
}

// execActive runs JavaScript in the active tab.
func (a *app) execActive(js string) {
	if t := a.commandTab(); t != nil && t.chromium != nil {
		t.chromium.Eval(js)
	}
}

// onCommand handles hotkeys and mouse-button navigation.
func (a *app) onCommand(id int) {
	t := a.commandTab()
	// Ctrl+1..8 are consecutive command IDs. A Go switch case matches one
	// value, not the whole numeric range, so dispatch the range explicitly.
	if id >= cmdSelectTab && id < cmdSelectTab+8 {
		if n := id - cmdSelectTab; n < len(a.tabs) { a.switchToTab(n) }
		return
	}
	switch id {
	case cmdBack:
		if t != nil && t.chromium != nil && t.chromium.CanGoBack() {
			t.chromium.GoBack()
			a.scheduleBarPush(false)
		}
	case cmdForward:
		if t != nil && t.chromium != nil && t.chromium.CanGoForward() {
			t.chromium.GoForward()
			a.scheduleBarPush(false)
		}
	case cmdReload:
		if t != nil && t.chromium != nil {
			if t.isStart {
				a.showStartPage(t)
			} else {
				t.chromium.Reload()
			}
		}
	case cmdHome:
		if t != nil {
			a.showStartPage(t)
		}
	case cmdFocusAddress:
		a.execActive("window.__okBubbleFocus&&window.__okBubbleFocus()")
	case cmdNewTab:
		// May be invoked from inside the engine's accelerator callback;
		// engine creation must happen in the window-proc context.
		a.postNewTab("")
	case cmdNewWindow:
		spawnNewWindow("")
	case cmdCloseTab:
		if len(a.tabs) > 0 {
			i := a.activeIdx
			a.postTask(func() { a.closeTab(i) })
		}
	case cmdNextTab:
		if len(a.tabs) > 1 {
			a.switchToTab((a.activeIdx + 1) % len(a.tabs))
		}
	case cmdPrevTab:
		if len(a.tabs) > 1 {
			a.switchToTab((a.activeIdx - 1 + len(a.tabs)) % len(a.tabs))
		}
	case cmdZoomIn:
		a.setZoom(1.25)
	case cmdZoomOut:
		a.setZoom(0.8)
	case cmdZoomReset:
		a.setZoom(0) // sentinel: reset to 1.0
	case cmdPrint:
		if t != nil && t.chromium != nil {
			t.chromium.Eval("window.print()")
		}
	case cmdFullscreen:
		a.toggleFullscreen()

	// Chrome-compatible additions.
	case cmdLastTab:
		if len(a.tabs) > 0 {
			a.switchToTab(len(a.tabs) - 1)
		}
	case cmdReopenTab:
		if n := len(a.closedTabs); n > 0 {
			url := a.closedTabs[n-1]
			a.closedTabs = a.closedTabs[:n-1]
			a.postNewTab(url)
		}
	case cmdHardReload:
		if t != nil && t.chromium != nil {
			if t.isStart {
				a.showStartPage(t)
			} else {
				t.chromium.CallDevToolsProtocol("Page.reload", `{"ignoreCache":true}`)
			}
		}
	case cmdCloseWindow:
		win.DestroyWindow(a.hwnd)
	case cmdFind:
		a.execActive("window.__okFind&&window.__okFind()")
	case cmdFindNext:
		a.execActive("window.__okFindCycle&&window.__okFindCycle(1)")
	case cmdFindPrev:
		a.execActive("window.__okFindCycle&&window.__okFindCycle(-1)")
	case cmdDevTools:
		if t != nil && t.chromium != nil {
			t.chromium.OpenDevTools()
		}
	case cmdBookmark:
		if t != nil && t.url != "" && !t.isStart && !strings.HasPrefix(t.url, "okbrowser://") {
			a.store.ToggleBookmark(t.url, t.title)
			a.pushBarState()
		}
	case cmdHistoryPage:
		a.navigateTab(a.active(), "okbrowser://history")
	case cmdBmPage:
		a.navigateTab(a.active(), "okbrowser://bookmarks")
	case cmdDownloadsPg:
		a.navigateTab(a.active(), "okbrowser://downloads")
	case cmdIncognito:
		spawnIncognito()
	}
}

// setZoom multiplies the active tab's zoom (0 resets to 100%).
func (a *app) setZoom(mult float64) {
	t := a.active()
	if t == nil {
		return
	}
	if mult == 0 {
		t.zoom = 1.0
	} else {
		t.zoom *= mult
		if t.zoom < 0.25 {
			t.zoom = 0.25
		}
		if t.zoom > 5.0 {
			t.zoom = 5.0
		}
	}
	a.applyZoomTab(t)
}

// onDpiChanged rescales the window.
func (a *app) onDpiChanged(dpi int, suggested *win.RECT) {
	if dpi > 0 {
		a.scale = float64(dpi) / 96.0
	}
	win.SetWindowPos(a.hwnd, 0, suggested.Left, suggested.Top,
		suggested.Right-suggested.Left, suggested.Bottom-suggested.Top,
		win.SWP_NOZORDER|win.SWP_NOACTIVATE)
}

// toggleFullscreen enters or leaves borderless fullscreen (F11).
func (a *app) toggleFullscreen() {
	if !a.fullscreen {
		a.savedStyle = win.GetWindowLong(a.hwnd, win.GWL_STYLE)
		a.savedPlacement.Length = uint32(unsafe.Sizeof(win.WINDOWPLACEMENT{}))
		win.GetWindowPlacement(a.hwnd, &a.savedPlacement)

		var mi win.MONITORINFO
		mi.CbSize = uint32(unsafe.Sizeof(mi))
		mon := win.MonitorFromWindow(a.hwnd, win.MONITOR_DEFAULTTONEAREST)
		if mon != 0 && win.GetMonitorInfo(mon, &mi) {
			win.SetWindowLong(a.hwnd, win.GWL_STYLE,
				a.savedStyle&^(win.WS_CAPTION|win.WS_THICKFRAME))
			win.SetWindowPos(a.hwnd, 0,
				mi.RcMonitor.Left, mi.RcMonitor.Top,
				mi.RcMonitor.Right-mi.RcMonitor.Left,
				mi.RcMonitor.Bottom-mi.RcMonitor.Top,
				win.SWP_NOZORDER|win.SWP_FRAMECHANGED)
			a.fullscreen = true
		}
		return
	}
	win.SetWindowLong(a.hwnd, win.GWL_STYLE, a.savedStyle)
	win.SetWindowPlacement(a.hwnd, &a.savedPlacement)
	var rc win.RECT
	win.GetWindowRect(a.hwnd, &rc)
	win.SetWindowPos(a.hwnd, 0, rc.Left, rc.Top,
		rc.Right-rc.Left, rc.Bottom-rc.Top,
		win.SWP_NOZORDER|win.SWP_FRAMECHANGED)
	a.fullscreen = false
}

// scaled scales a 96-DPI design value to the current DPI.
func (a *app) scaled(v int32) int32 {
	if a.scale == 1 {
		return v
	}
	return int32(float64(v)*a.scale + 0.5)
}
